import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";
import { decodeBase64 } from "https://deno.land/std@0.224.0/encoding/base64.ts";

const TENANT_ID = "c0000000-0000-0000-0000-000000000002";
const PNG_B64 = "
";

Deno.serve(async () => {
  try {
    const admin = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const bytes = decodeBase64(PNG_B64);
    const path = `${TENANT_ID}/logo-email.png`;
    const up = await admin.storage.from("tenant-assets").upload(path, bytes, {
      contentType: "image/png", upsert: true, cacheControl: "31536000",
    });
    if (up.error) throw up.error;
    const { data: pub } = admin.storage.from("tenant-assets").getPublicUrl(path);
    const url = `${pub.publicUrl}?v=${Date.now()}`;
    const { error: sErr } = await admin.from("tenant_settings").upsert({
      tenant_id: TENANT_ID, category: "branding", setting_key: "email_logo_url", setting_value: url,
    }, { onConflict: "tenant_id,category,setting_key" });
    if (sErr) throw sErr;
    return new Response(JSON.stringify({ ok: true, url }), { headers: { "Content-Type": "application/json" } });
  } catch (e) {
    return new Response(JSON.stringify({ error: (e as Error).message }), { status: 500 });
  }
});
